negativeExample:
package test;

import org.eclipse.swt.events.SelectionEvent;
import org.eclipse.swt.events.SelectionListener;

public class TestClass {
    public void method() {
        SelectionListener listener = new SelectionListener() {
            @Override
            public void widgetSelected(SelectionEvent e) {}
            @Override
            public void widgetDefaultSelected(SelectionEvent e) {}
        };
        // Should not match: argument is not null
        listener.widgetSelected(new SelectionEvent(null, null, 0));

        // Should not match: receiver is not SelectionListener
        MyOtherClass other = new MyOtherClass();
        other.widgetSelected(null);

        // Should not match: method has different name
        listener.widgetDefaultSelected(null);
    }

    static class MyOtherClass {
        public void widgetSelected(Object o) {}
    }
}
